WITH metrics AS (SELECT *, NTILE(4) OVER (PARTITION BY job_title ORDER BY salary, id) AS salary_bucket, LAST_VALUE(job_title, TRUE) OVER (PARTITION BY level ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_job_title, ROUND(salary / SUM(salary) OVER (PARTITION BY dept_id, level), 4) AS salary_share, MAX(salary) OVER (PARTITION BY manager_id) AS manager_id_max_salary, LEAD(salary, 1) OVER (PARTITION BY job_title ORDER BY salary, id) AS next_salary FROM employees) SELECT id, full_name, email, job_title, hire_date, level, salary_bucket, last_known_job_title, manager_id_max_salary FROM metrics ORDER BY id DESC LIMIT 20;
